\coordinate (A) at (-0.8,0.6);
\coordinate (M) at (0,0.6);
\draw[black,line width=0.8pt] (O) circle[radius=1];
\draw[black,line width=0.8pt] (-0.8,-1) rectangle (0.8,0.6);
\draw[black,line width=0.4pt] (A)--node[midway,below left] {$r$} (O)--node[midway,right] {$x-r$} (M);
\path (A)--node[midway,above] {$\frac{x}{2}$} (M);
\draw[black,line width=0.4pt] ($(M)!0.12!(A)$)--($(M)!0.12!(A)+(M)!0.16!(O)-(M)$)--($(M)!0.16!(O)$);
\end{tikzpicture}
